package com.bankpli.javabank.account;import static org.junit.jupiter.api.Assertions.*;import java.math.BigDecimal;import org.junit.jupiter.api.Test;
class FinancialCalculatorsTest{private final MortgageCalculator mortgage=new MortgageCalculator();private final InterestService interest=new InterestService();private final OverdraftService overdraft=new OverdraftService();@Test void mortgageCases(){assertEquals(new BigDecimal("599.55"),mortgage.payment(new BigDecimal("100000"),new BigDecimal("0.06"),360));assertEquals(new BigDecimal("277.78"),mortgage.payment(new BigDecimal("100000"),BigDecimal.ZERO,360));assertThrows(IllegalArgumentException.class,()->mortgage.payment(BigDecimal.TEN,BigDecimal.ONE,0));}@Test void interestCases(){assertEquals(new BigDecimal("41.10"),interest.accrue(new BigDecimal("10000"),new BigDecimal("0.05"),30));assertEquals(new BigDecimal("0.00"),interest.accrue(BigDecimal.TEN,BigDecimal.ONE,0));assertEquals(new BigDecimal("-41.10"),interest.accrue(new BigDecimal("-10000"),new BigDecimal("0.05"),30));}@Test void overdraftBoundaries(){assertTrue(overdraft.withinLimit(b("100"),b("50"),b("200")));assertTrue(overdraft.withinLimit(b("100"),b("250"),b("200")));assertFalse(overdraft.withinLimit(b("100"),b("350"),b("200")));assertTrue(overdraft.withinLimit(b("100"),b("300"),b("200")));}private BigDecimal b(String v){return new BigDecimal(v);}}
